import {interviewEnrichment} from "./interview-enrichment.js?v=20261009-interview-coaching-1";
import {interviewModelAnswers} from "./interview-model-answers.js?v=20261009-direct-answers-2";
// Edit named fields below. group is the visible learning field; category preserves existing deep links.
const groups = [];
const prefixes = ["DS", "JAVA", "DB", "OS", "NET", "SPR", "GIT", "DK", "CN", "AI"];
let groupIndex = 0;
function addGroup(group, category, jobTags, sourceIds, rows) {
  const prefix = prefixes[groupIndex++];
  groups.push(...rows.map((row, index) => ({group, category, jobTags, sourceIds,
    code: prefix + "-" + String(index + 1).padStart(3, "0"), ...row,
    answer: row.shortAnswer, extra: row.detailedAnswer}))); // Legacy read-only consumers stay compatible.
}
function q(id, subCategory, difficulty, question, shortAnswer, detailedAnswer, keywords, followUps, overrides = {}) {
  return {id, subCategory, difficulty, question, shortAnswer, detailedAnswer, keywords, followUps, ...overrides};
}

